import type { Href } from "expo-router";

import type { Me } from "@gugu/contracts";

/**
 * Runtime-built app path as an Expo Router href. Typed routes (`.expo/types`, generated by the dev
 * server) make `Href` a union of known paths; without them it is `string`.
 */
export function toHref(path: string): Href {
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion -- needed once typed routes are generated
  return path as Href;
}

/**
 * Where to go after a successful sign-in. Pending salons (registered with this email but never
 * confirmed) need an explicit confirm step first — sign-in alone never activates them.
 */
export function afterSignInHref(user: Me, target: string): Href {
  if (user.memberships.some((m) => m.status === "pending_verification")) {
    const locale = /^\/(vi|en)(?=\/|$)/.exec(target)?.[1] ?? "vi";
    return toHref(`/${locale}/auth/pending-salons?next=${encodeURIComponent(target)}`);
  }
  return toHref(target);
}
